var i=`1307-milanesa-napolitana`;var n=`world-1307`;var t=`AR`;var r=`south-america`;var o=4;var s=53;var l={en:`Milanesa Napolitana`,ua:`Міланеса наполітана`};var d={en:`Milanesa Napolitana is a dish from Argentina featuring beef round, all-purpose flour, chicken egg, breadcrumbs. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Міланеса наполітана, страва кухні країни Аргентина з такими основними складниками: яловичий стегновий відруб, пшеничне борошно універсальне, куряче яйце, панірувальні сухарі. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:12,i:[[`beef-round`,780,`g`],[`all-purpose-flour`,120,`g`],[`chicken-egg`,3,`pcs`],[`breadcrumbs`,230,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,180,`ml`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:8,i:[[`tomato-passata`,250,`ml`],[`smoked-ham`,170,`g`],[`mozzarella`,280,`g`]]},{en:`Grill the marinated portions from the preceding steps, turning to cook evenly and checking the safe internal temperature.`,ua:`Готуйте замариновані порції на грилі, перевертаючи для рівномірного нагрівання та перевіряючи безпечну температуру всередині.`,t:[`grilling`],m:13,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`dried-oregano`,5,`g`]]}];var h={slug:i,id:n,country:`AR`,region:r,servings:4,minutes:53,title:l,text:d,steps:g};export{t as country,h as default,n as id,s as minutes,r as region,o as servings,i as slug,g as steps,d as text,l as title};